// =====================================================================
// FUENTE: LA CARD DE NOTION, CON EL WEBHOOK COMO RESPALDO.
// El webhook manda solo unos pocos campos; la card tiene el resto. Si
// Notion falla, ese nodo esta en continueRegularOutput y aca queda lo
// que trajo el webhook, asi que el flujo no se corta por eso.
// =====================================================================
let wh = {};
try {
  wh = $('Link a discovery cargado').first().json || {};
  while (wh.body && typeof wh.body === 'object') { wh = wh.body; }
} catch (e) {}
const card = $input.first().json || {};
let raw = Object.assign({}, wh, (card && !card.error) ? card : {});
while (raw.body && typeof raw.body === 'object') {
  raw = raw.body;
}

const props = raw.properties || {};

let linkDiscovery = "";
const getPropValue = (p) => {
  if (!p) return "";
  if (typeof p === 'string') return p;
  if (p.url) return p.url;
  if (p.email) return p.email;
  if (p.rich_text && p.rich_text[0]) return p.rich_text[0].plain_text || p.rich_text[0].text?.content || "";
  if (p.title && p.title[0]) return p.title[0].plain_text || p.title[0].text?.content || "";
  return "";
};

const notionEmails = [];

// =====================================================================
// LOS CORREOS VIENEN EN CAMPOS PLANOS, NO EN raw.properties.
//
// El nodo de Notion usa simple:true, asi que devuelve
// property_email_kdm_sdr: "edalvarez@banesco.com" -- un string suelto.
// El barrido de mas abajo espera el formato CRUDO de la API
// ({email: "..."}), que con simple:true no existe: raw.properties viene
// vacio y notionEmails quedaba en [] SIEMPRE. El borrador salia diciendo
// "(Completar emails de los interlocutores)" con el dato ahi al lado.
//
// El del KDM va primero porque es el interlocutor real de la llamada.
// =====================================================================
const PRIORIDAD_MAIL = ['property_email_kdm_sdr', 'property_email_2', 'property_email_facturaci_n'];
for (const k of PRIORIDAD_MAIL) {
  const v = raw[k];
  if (typeof v === 'string' && v.indexOf('@') !== -1 && v.indexOf('@xtract.app') === -1) notionEmails.push(v.trim());
}
for (const [k, v] of Object.entries(raw)) {
  if (typeof v !== 'string' || v.indexOf('@') === -1) continue;
  if (!/mail|correo/i.test(k)) continue;
  if (v.indexOf('@xtract.app') !== -1) continue;
  if (notionEmails.indexOf(v.trim()) === -1) notionEmails.push(v.trim());
}

for (const [k, v] of Object.entries(props)) {
  if (v.email) notionEmails.push(v.email);
  if (v.people) {
    v.people.forEach(p => {
      if (p.person && p.person.email && !p.person.email.includes('@xtract.app')) {
        notionEmails.push(p.person.email);
      }
    });
  }
  if (k.toLowerCase().includes('mail') || k.toLowerCase().includes('correo') || k.toLowerCase().includes('email')) {
    const val = getPropValue(v);
    if (val && val.includes('@') && !val.includes('@xtract.app')) notionEmails.push(val);
  }
}

// Buscar link de discovery en props
for (const [k, v] of Object.entries(props)) {
  if (k.toLowerCase().includes('discovery') || k.toLowerCase().includes('transcrip') || k.toLowerCase().includes('drive') || k.toLowerCase().includes('doc')) {
    const val = getPropValue(v);
    if (val && (val.includes('drive.google.com') || val.includes('docs.google.com'))) {
      linkDiscovery = val;
      break;
    }
  }
}

// Buscar link de discovery en campos planos de raw
if (!linkDiscovery) {
  for (const [k, v] of Object.entries(raw)) {
    if (typeof v === 'string' && (v.includes('drive.google.com') || v.includes('docs.google.com'))) {
      linkDiscovery = v;
      break;
    }
  }
}

let fileId = "";
const match = (linkDiscovery || "").match(/\/d\/([a-zA-Z0-9_-]+)/);
if (match) {
  fileId = match[1];
} else {
  const matchId = (linkDiscovery || "").match(/id=([a-zA-Z0-9_-]+)/);
  if (matchId) fileId = matchId[1];
}

let empresa = "";
for (const [k, v] of Object.entries(props)) {
  if (k.toLowerCase().includes('empresa') || k.toLowerCase().includes('name') || k.toLowerCase().includes('title') || k.toLowerCase().includes('cliente')) {
    empresa = getPropValue(v);
    if (empresa) break;
  }
}
if (!empresa) empresa = raw.property_nombre_oportunidad || raw.empresa || raw.name || "Cliente";

// property_owner viene de Notion como ARRAY de mails; el webhook lo manda
// como string suelto. Se aceptan las dos formas antes de caer al default.
const ownerCard = Array.isArray(raw.property_owner) ? raw.property_owner[0] : raw.property_owner;
let ownerEmail = ownerCard || raw.owner || raw.ownerEmail || "nicolas.gonzalez@xtract.app";
for (const [k, v] of Object.entries(props)) {
  if (k.toLowerCase().includes('owner') || k.toLowerCase().includes('responsable')) {
    if (v.people && v.people[0] && v.people[0].person && v.people[0].person.email) {
      ownerEmail = v.people[0].person.email;
      break;
    }
  }
}

let interlocutor = "";
for (const [k, v] of Object.entries(props)) {
  if (k.toLowerCase().includes('contacto') || k.toLowerCase().includes('persona') || k.toLowerCase().includes('asistente')) {
    interlocutor = getPropValue(v);
    if (interlocutor) break;
  }
}

const rawId = (raw.id || raw.page_id || "").replace(/-/g, "");
const notionUrl = raw.url || (rawId ? ("https://www.notion.so/" + rawId) : "");

// Nombre del interlocutor: segunda señal de la guarda de transcripcion.
// Es mas confiable que el nombre de la empresa, porque la gente NO nombra
// su propia empresa en su llamada, pero su nombre aparece en cada linea.
const nombreKdm = raw.property_nombre_kdm_sdr || interlocutor || "";

// El ERP como DATO de la card, no como inferencia del modelo sobre el
// audio. Medido: el modelo devolvio 'Subio' donde la card dice 'Xubio', y
// 'Walbot' donde la card no tiene nada cargado.
const sistemaCard = raw.property_que_sistema_usan || "";

// Volumen de facturas. Si la card NO lo tiene, el mail lo PIDE: es el dato
// que Nicolas reclama a mano en sus mails reales ("quedo a la espera del
// volumen aproximado de documentos que procesan por mes"). Medido: falta
// en 4 de cada 12 cards con discovery.
const cantidadFacturas = raw.property_cantidad_de_facturas || "";

const transcripcion = raw.transcripcion || "";
return [{ json: {
  transcripcion,
  fileId,
  linkDiscovery,
  empresa,
  interlocutor,
  nombreKdm,
  sistemaCard,
  cantidadFacturas,
  ownerEmail,
  notionUrl,
  notionEmails,
  raw
} }];

const prevData = $('Code - Extraer Datos').first().json || {};
let txt = String($input.first().json.data || prevData.transcripcion || '').trim();
if (txt.length > 22000) {
  txt = txt.slice(0, 22000) + '\n...[transcripción resumida]';
}
return [{ json: { transcripcion: txt } }];

