// =====================================================================
// MODO PRUEBA -- UNICO LUGAR PARA CAMBIARLO
// Con un valor cargado, TODOS los borradores van a este DM y NUNCA al
// comercial real. Para pasar a produccion, dejarlo en '' (string vacio).
// =====================================================================
const FORZAR_DESTINATARIO = 'U0BJLTDCAMR';

const notion = $('Code - Extraer Datos').first().json || {};
const iaRaw = $('IA - Redactar borrador de correo').first().json || {};
const ia = iaRaw.output || iaRaw;

const idioma = (ia.idioma || 'es').toLowerCase().trim();
const esPt = (idioma === 'pt');

// 1. Resolver Destinatarios (Emails del cliente)
const emailsNotion = Array.isArray(notion.emails) ? notion.emails : (notion.emails ? [notion.emails] : []);
const emailsIa = Array.isArray(ia.emails_destinatarios) ? ia.emails_destinatarios : (ia.emails_destinatarios ? [ia.emails_destinatarios] : []);
const todosEmails = [...new Set([...emailsNotion, ...emailsIa].map(e => String(e || '').trim().toLowerCase()))].filter(e => e && e.includes('@'));
const paraTexto = todosEmails.length ? todosEmails.join(', ') : (esPt ? '*(Completar e-mails dos interlocutores)*' : '*(Completar emails de los interlocutores)*');

const empresa = notion.property_nombre_oportunidad || notion.empresa || 'Cliente';
const erpDetectado = (notion.sistema || notion.erp || '').trim();

let defaultSubject = '';
if (esPt) {
  defaultSubject = 'Xtract + ' + empresa + ': Automação de notas fiscais' + (erpDetectado ? ' no ' + erpDetectado : '') + ' e próximos passos';
} else {
  defaultSubject = 'Xtract + ' + empresa + ': Automatización de facturas' + (erpDetectado ? ' en ' + erpDetectado : '') + ' y próximos pasos';
}
const subjectPersonalizado = ia.asunto_email || defaultSubject;

// 2. Nombres y Comercial
const interlocutores = (ia.interlocutores || notion.persona || (esPt ? 'equipe' : 'equipo')).trim();
const rawOwner = (Array.isArray(notion.owner) ? notion.owner[0] : notion.owner) || notion.ownerEmail || '';
const ownerLocal = rawOwner.split('@')[0].replace(/[._-]+/g, ' ');
const nombreComercial = ownerLocal ? ownerLocal.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ') : 'Nicolás';

// 3. Construir Bloques del Correo (Formato Corto y Ejecutivo)
let saludoDefault = '';
if (esPt) {
  saludoDefault = 'Olá ' + interlocutores + ', boa tarde!\nMuito obrigado pelo tempo na nossa conversa de hoje.';
} else {
  saludoDefault = 'Hola ' + interlocutores + ', buenas tardes.\nMuchas gracias por el tiempo en la reunión de hoy.';
}
const saludo = ia.saludo_intro || saludoDefault;

// Bullets de desafíos (máximo 2 o 3 concisos)
const puntosRaw = Array.isArray(ia.desafios_puntos) ? ia.desafios_puntos : (ia.desafios_puntos ? [ia.desafios_puntos] : []);
const puntos = puntosRaw.slice(0, 3);
const bloqueDesafios = puntos.length ? puntos.map(p => '• ' + String(p).replace(/^[•\-\*]\s*/, '').trim()).join('\n') : (ia.desafio || '');
const introDesafios = esPt ? 'Compartilho um breve resumo do que conversamos:' : 'Comparto un breve resumen de los puntos principales:';

// Párrafo de solución (conciso)
const bloqueSolucion = ia.solucion_encaje || ia.solucion || '';

// Documentación de API (si aplica)
let bloqueApi = '';
if (ia.solicito_documentacion_api === true || ia.solicito_documentacion_api === 'true') {
  if (esPt) {
    bloqueApi = '\nConforme combinamos, compartilho a documentação da nossa API REST: https://xtractapi.docs.apiary.io/#reference para validação da integração com o suporte do ERP.';
  } else {
    bloqueApi = '\nTal como acordamos, les comparto la documentación de la API Rest: https://xtractapi.docs.apiary.io/#reference para que el equipo técnico pueda validar los endpoints.';
  }
}

// Próximos pasos (siempre positivo y proactivo a demo/propuesta, sin WhatsApp)
let defaultProximos = '';
if (esPt) {
  defaultProximos = 'Como próximo passo, coordenamos uma reunião na próxima semana para demonstrar a ferramenta de ponta a ponta e apresentar a proposta.';
} else {
  defaultProximos = 'Como próximo paso, coordinemos una reunión de 30 minutos la próxima semana para mostrarles la herramienta de punta a punta y presentarles la propuesta comercial.';
}
let rawProximos = ia.proximos_pasos || defaultProximos;
rawProximos = rawProximos.replace(/te env[íi]o por whatsapp[^.\n]*[.\n]?/gi, '').replace(/whatsapp/gi, 'correo').trim();
const bloqueProximos = rawProximos || defaultProximos;

// Casos de Éxito oficiales (URLs directas para preview/unfurl en Slack)
const erpLower = (notion.sistema || notion.erp || '').toLowerCase();
const empresaLower = empresa.toLowerCase();

let videosRelevantes = [];
if (esPt) {
  if (erpLower.includes('sap')) {
    videosRelevantes.push('• Caso de sucesso Pomelo (SAP): https://www.youtube.com/watch?v=yJtHFuTnwSA');
  } else {
    videosRelevantes.push('• Caso de sucesso MODO: https://www.youtube.com/watch?v=k2uYl5kSGBQ');
  }
} else if (erpLower.includes('netsuite')) {
  videosRelevantes.push('• Caso InvGate (NetSuite): https://www.youtube.com/watch?v=4xFCkoxat1o');
} else if (erpLower.includes('sap')) {
  videosRelevantes.push('• Caso Pomelo (SAP): https://www.youtube.com/watch?v=ikDLA5HjQbs');
} else if (empresaLower.includes('salud') || empresaLower.includes('sanatorio') || empresaLower.includes('clinica')) {
  videosRelevantes.push('• Caso SanCor Salud: https://www.youtube.com/watch?v=I8J-vd5U5ck');
} else {
  videosRelevantes.push('• Caso MODO: https://www.youtube.com/watch?v=k2uYl5kSGBQ');
}
const bloqueCasosExito = videosRelevantes.join('\n');

// Cierre y firma
const cierreDefault = esPt ? 'Fico à disposição.\nAbraços,' : 'Quedo atento.\nSaludos y gracias,';
const cierre = (ia.cierre_despedida || cierreDefault) + '\n' + nombreComercial;

// 4. Ensamble del Borrador Completo
const cuerpoEmail = [
  saludo,
  (introDesafios + '\n' + bloqueDesafios).trim(),
  bloqueSolucion,
  bloqueApi,
  bloqueProximos,
  bloqueCasosExito,
  cierre
].map(s => String(s || '').trim()).filter(Boolean).join('\n\n');

// 5. Matching en Cascada para encontrar el ID de Slack del Comercial
const norm = s => String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const emailNorm = norm(rawOwner);
const local = norm(rawOwner.split('@')[0]);
const comoNombre = local.replace(/[._-]+/g, ' ');

const KNOWN_OWNERS = {
  'nicolas.gonzalez@xtract.app': 'U02MCAHHM1T',
  'wenceslao.hoepner@xtract.app': 'U0BBASA0F60',
  'damian.deggeller@xtract.app': 'U09PYEWUHGF',
  'greta.bruno@xtract.app': 'U096BLX5864',
  'ian.brandan@xtract.app': 'U09FZ5MLF0E'
};

let usuarios = [];
try {
  const raw = $('Slack - Traer usuarios').first().json;
  usuarios = (raw.members || raw.users || []).filter(u => u && u.id && !u.deleted && !u.is_bot);
} catch(e) {}

const perfil = u => u.profile || {};
let owner = usuarios.find(u => norm(perfil(u).email) === emailNorm) || null;
if (!owner) owner = usuarios.find(u => norm(u.name) === local) || null;
if (!owner) owner = usuarios.find(u => norm(perfil(u).display_name) === local) || null;
if (!owner) owner = usuarios.find(u => norm(u.real_name) === comoNombre) || null;
if (!owner) owner = usuarios.find(u => norm(perfil(u).real_name) === comoNombre) || null;

const SLACK_FALLBACK_DM = 'U0BJLTDCAMR';
const ownerSlackIdReal = owner ? owner.id : (KNOWN_OWNERS[emailNorm] || SLACK_FALLBACK_DM);
const ownerSlackId = FORZAR_DESTINATARIO || ownerSlackIdReal;
const enModoPrueba = !!FORZAR_DESTINATARIO;
const esFallback = !owner && !KNOWN_OWNERS[emailNorm];

// Link a Notion
const rawId = (notion.id || notion.page_id || '').replace(/-/g, '');
const notionUrl = notion.url || (rawId ? ('https://www.notion.so/' + rawId) : '');

// 6. Mensaje Formateado para Slack
const tagIdioma = esPt ? ' 🇧🇷 *(Português)*' : ' 🌎 *(Español)*';
const footerCopia = esPt ? '_Pronto para copiar e enviar no Gmail / Outlook._' : '_Listo para copiar y enviar en Gmail / Outlook._';

const textoSlack = [
  (enModoPrueba ? ':test_tube: *MODO PRUEBA* — en producción esto le hubiera llegado a `' + ownerSlackIdReal + '`' : ''),
  ':incoming_envelope: *Borrador de Email Post-Discovery*' + tagIdioma + ' — ' + empresa,
  (ia.reunion_ya_agendada ? '📅 *Reunión pactada:* ' + (ia.detalle_reunion_agendada || 'Sí (en la llamada)') : '📅 *Reunión:* Pendiente de coordinar'),
  (notionUrl ? '• <' + notionUrl + '|Abrir card en Notion>' : ''),
  (esFallback ? '_Nota: Enviado a fallback de pruebas._' : ''),
  '',
  '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
  '*Para:* ' + paraTexto,
  '*Subject:* ' + subjectPersonalizado,
  '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
  '',
  cuerpoEmail,
  '',
  '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
  footerCopia
].filter(Boolean).join('\n');

return [{ json: {
  texto_slack: textoSlack,
  cuerpo_email: cuerpoEmail,
  idioma: idioma,
  para: paraTexto,
  subject: subjectPersonalizado,
  owner_slack_id: ownerSlackId,
  comercial: nombreComercial,
  empresa: empresa,
  notion_url: notionUrl
} }];
